{
	"$schema": "https://schemas.wp.org/trunk/block.json",
	"apiVersion": 3,
	"name": "rafaelfunchal/animated-raffle-winner",
	"version": "1.0",
	"title": "Animated Raffle Winner",
	"category": "widgets",
	"icon": "randomize",
	"description": "Create interactive raffles with number animation and fireworks",
	"example": {
		"attributes": {
			"startingNumber": 1,
			"endingNumber": 100,
			"raffleDuration": 5,
			"fullscreen": false,
			"animationType": "fireworks"
		}
	},
	"attributes": {
		"startingNumber": {
			"type": "number",
			"default": 1
		},
		"endingNumber": {
			"type": "number",
			"default": 100
		},
		"raffleDuration": {
			"type": "number",
			"default": 5
		},
		"fullscreen": {
			"type": "boolean",
			"default": false
		},
		"animationType": {
			"type": "string",
			"default": "fireworks"
		},
		"textSize": {
			"type": "string",
			"default": "medium"
		},
		"backgroundColor": {
			"type": "string"
		},
		"overlayOpacity": {
			"type": "number",
			"default": 100
		},
		"gradient": {
			"type": "string"
		},
		"buttonColor": {
			"type": "string"
		},
		"textColor": {
			"type": "string"
		},
		"buttonTextColor": {
			"type": "string"
		},
		"backgroundImageUrl": {
			"type": "string"
		},
		"backgroundImageId": {
			"type": "number"
		}
	},
	"supports": {
		"html": false,
		"align": ["wide", "full"]
	},
	"textdomain": "animated-raffle-winner",
	"editorScript": "file:./index.js",
	"editorStyle": "file:./index.css",
	"style": "file:./style-index.css",
	"viewScript": "file:./view.js"
}

/**
 * Registers a new block provided a unique name and an object defining its behavior.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-registration/
 */
import { registerBlockType } from '@wordpress/blocks';

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * All files containing `style` keyword are bundled together. The code used
 * gets applied both to the front of your site and to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import './style.scss';

/**
 * Internal dependencies
 */
import Edit from './edit';
import save from './save';
import metadata from './block.json';

/**
 * Every block starts by registering a new block type definition.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-registration/
 */
registerBlockType( metadata.name, {
	/**
	 * @see ./edit.js
	 */
	edit: Edit,

	/**
	 * @see ./save.js
	 */
	save,
} );

/**
 * Retrieves the translation of text.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-i18n/
 */
import { __ } from '@wordpress/i18n';

/**
 * React hook that is used to mark the block wrapper element.
 * It provides all the necessary props like the class name.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-block-editor/#useblockprops
 */
import { useBlockProps, InspectorControls, PanelColorSettings, MediaUpload, MediaUploadCheck, getGradientValueBySlug } from '@wordpress/block-editor';

/**
 * WordPress components
 */
import { PanelBody, TextControl, RangeControl, ToggleControl, SelectControl, Button, ButtonGroup } from '@wordpress/components';

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * Those files can contain any CSS code that gets applied to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import './editor.scss';

/**
 * The edit function describes the structure of your block in the context of the
 * editor. This represents what the editor will render when the block is used.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-edit-save/#edit
 *
 * @return {Element} Element to render.
 */
export default function Edit( { attributes, setAttributes } ) {
	const {
		startingNumber,
		endingNumber,
		raffleDuration,
		fullscreen,
		animationType,
		textSize,
		backgroundColor,
		overlayOpacity,
		gradient,
		buttonColor,
		textColor,
		buttonTextColor,
		backgroundImageUrl,
		backgroundImageId,
	} = attributes;

	const applyColorOpacity = ( colorValue, opacityValue ) => {
		const opacity = Math.max( 0, Math.min( 100, opacityValue ?? 100 ) ) / 100;
		const color = colorValue?.trim();

		if ( ! color ) {
			return colorValue;
		}

		const hexMatch = color.match( /^#([a-fA-F0-9]{3}|[a-fA-F0-9]{6})$/ );
		if ( hexMatch ) {
			const hex = hexMatch[ 1 ];
			const normalizedHex =
				hex.length === 3
					? hex.split( '' ).map( ( char ) => char + char ).join( '' )
					: hex;
			const red = parseInt( normalizedHex.slice( 0, 2 ), 16 );
			const green = parseInt( normalizedHex.slice( 2, 4 ), 16 );
			const blue = parseInt( normalizedHex.slice( 4, 6 ), 16 );
			return `rgba(${ red }, ${ green }, ${ blue }, ${ opacity })`;
		}

		const rgbMatch = color.match(
			/^rgba?\(\s*([0-9.]+)\s*,\s*([0-9.]+)\s*,\s*([0-9.]+)(?:\s*,\s*[0-9.]+\s*)?\)$/i
		);
		if ( rgbMatch ) {
			return `rgba(${ rgbMatch[ 1 ] }, ${ rgbMatch[ 2 ] }, ${ rgbMatch[ 3 ] }, ${ opacity })`;
		}

		return colorValue;
	};

	// Get background style - resolve gradient slug if needed
	// Sanitize CSS values to prevent injection
	// Supports custom multi-color gradients
	const backgroundStyle = {};
	if ( gradient ) {
		// Try to resolve gradient slug, fallback to direct value (supports custom gradients)
		const gradientValue = getGradientValueBySlug( gradient ) || gradient;
		// Sanitize gradient - block script injection attempts but allow CSS gradient syntax
		// Allows linear-gradient, radial-gradient, conic-gradient with multiple color stops
		if ( gradientValue && ! /<script|javascript:|on\w+\s*=/i.test( gradientValue ) ) {
			backgroundStyle.background = gradientValue;
		}
	} else if ( backgroundColor ) {
		// Sanitize color value - block script injection attempts
		if ( backgroundColor && ! /<script|javascript:|on\w+\s*=/i.test( backgroundColor ) ) {
			backgroundStyle.background = applyColorOpacity( backgroundColor, overlayOpacity );
		}
	}
	if ( backgroundImageUrl && ! /<script|javascript:/i.test( backgroundImageUrl ) ) {
		if ( gradient && backgroundStyle.background ) {
			backgroundStyle.backgroundImage = `${ backgroundStyle.background }, url("${ backgroundImageUrl }")`;
			delete backgroundStyle.background;
		} else if ( backgroundColor && backgroundStyle.background ) {
			const overlayColor = backgroundStyle.background;
			delete backgroundStyle.background;
			backgroundStyle.backgroundImage = `linear-gradient(${ overlayColor }, ${ overlayColor }), url("${ backgroundImageUrl }")`;
		} else {
			backgroundStyle.backgroundImage = `url("${ backgroundImageUrl }")`;
		}
		backgroundStyle.backgroundSize = 'cover';
		backgroundStyle.backgroundPosition = 'center';
		backgroundStyle.backgroundRepeat = 'no-repeat';
	}

	// Get button color style - sanitize CSS values to prevent injection
	const buttonStyle = {};
	if ( buttonColor ) {
		// Sanitize color value - block script injection attempts
		if ( buttonColor && ! /<script|javascript:|on\w+\s*=/i.test( buttonColor ) ) {
			buttonStyle.backgroundColor = buttonColor;
		}
	}
	if ( buttonTextColor ) {
		// Sanitize color value - block script injection attempts
		if ( buttonTextColor && ! /<script|javascript:|on\w+\s*=/i.test( buttonTextColor ) ) {
			buttonStyle.color = buttonTextColor;
		}
	}

	// Get text color style - sanitize CSS values to prevent injection
	const textStyle = {};
	if ( textColor ) {
		// Sanitize color value - block script injection attempts
		if ( textColor && ! /<script|javascript:|on\w+\s*=/i.test( textColor ) ) {
			textStyle.color = textColor;
		}
	}

	// Get accent color style for strong elements and raffle-result (uses button background color)
	const accentStyle = {};
	if ( buttonColor ) {
		// Sanitize color value - block script injection attempts
		if ( buttonColor && ! /<script|javascript:|on\w+\s*=/i.test( buttonColor ) ) {
			accentStyle.color = buttonColor;
		}
	}

	const blockProps = useBlockProps( {
		className: 'animated-raffle-winner-block',
	} );

	const animationOptions = [
		{ label: __( 'Fireworks', 'animated-raffle-winner' ), value: 'fireworks' },
		{ label: __( 'Confetti', 'animated-raffle-winner' ), value: 'confetti' },
		{ label: __( 'Stars', 'animated-raffle-winner' ), value: 'stars' },
		{ label: __( 'Balloons', 'animated-raffle-winner' ), value: 'balloons' },
	];
	const textSizeOptions = [
		{ label: __( 'Extra Small', 'animated-raffle-winner' ), value: 'very-small' },
		{ label: __( 'Small', 'animated-raffle-winner' ), value: 'small' },
		{ label: __( 'Medium', 'animated-raffle-winner' ), value: 'medium' },
		{ label: __( 'Large', 'animated-raffle-winner' ), value: 'large' },
		{ label: __( 'Extra Large', 'animated-raffle-winner' ), value: 'super-large' },
	];

	return (
		<>
			<InspectorControls>
				<PanelBody title={ __( 'Raffle Settings', 'animated-raffle-winner' ) }>
					<TextControl
						label={ __( 'Starting Number', 'animated-raffle-winner' ) }
						type="number"
						value={ startingNumber }
						onChange={ ( value ) => {
							const num = parseInt( value, 10 );
							if ( ! isNaN( num ) && num >= -999999 && num <= 999999 ) {
								setAttributes( { startingNumber: num } );
							}
						} }
						help={ __( 'The lowest number in the range (-999999 to 999999)', 'animated-raffle-winner' ) }
					/>
					<TextControl
						label={ __( 'Ending Number', 'animated-raffle-winner' ) }
						type="number"
						value={ endingNumber }
						onChange={ ( value ) => {
							const num = parseInt( value, 10 );
							if ( ! isNaN( num ) && num >= -999999 && num <= 999999 ) {
								setAttributes( { endingNumber: num } );
							}
						} }
						help={ __( 'The highest number in the range (-999999 to 999999)', 'animated-raffle-winner' ) }
					/>
					<RangeControl
						label={ __( 'Raffle Duration (seconds)', 'animated-raffle-winner' ) }
						value={ raffleDuration }
						onChange={ ( value ) =>
							setAttributes( { raffleDuration: value } )
						}
						min={ 1 }
						max={ 15 }
						step={ 1 }
						help={ __( 'Duration of the animation before revealing the result', 'animated-raffle-winner' ) }
					/>
				</PanelBody>
				<PanelBody title={ __( 'Display Settings', 'animated-raffle-winner' ) } initialOpen={ false }>
					<MediaUploadCheck>
						<MediaUpload
							onSelect={ ( media ) =>
								setAttributes( {
									backgroundImageUrl: media?.url || undefined,
									backgroundImageId: media?.id || undefined,
								} )
							}
							allowedTypes={ [ 'image' ] }
							value={ backgroundImageId }
							render={ ( { open } ) => (
								<Button variant="secondary" onClick={ open }>
									{ backgroundImageUrl
										? __( 'Replace Background Image', 'animated-raffle-winner' )
										: __( 'Select Background Image', 'animated-raffle-winner' ) }
								</Button>
							) }
						/>
					</MediaUploadCheck>
					{ backgroundImageUrl && (
						<>
							<p>{ __( 'Background image selected.', 'animated-raffle-winner' ) }</p>
							<img
								src={ backgroundImageUrl }
								alt={ __( 'Selected background preview', 'animated-raffle-winner' ) }
								style={ {
									display: 'block',
									width: '100%',
									height: 'auto',
									maxHeight: '120px',
									objectFit: 'cover',
									borderRadius: '6px',
									marginBottom: '10px',
								} }
							/>
							<Button
								variant="tertiary"
								onClick={ () =>
									setAttributes( {
										backgroundImageUrl: undefined,
										backgroundImageId: undefined,
									} )
								}
							>
								{ __( 'Remove Background Image', 'animated-raffle-winner' ) }
							</Button>
						</>
					) }
					<PanelColorSettings
						title={ __( 'Background/Overlay Color', 'animated-raffle-winner' ) }
						colorSettings={ [
							{
								value: backgroundColor,
								onChange: ( value ) => {
									setAttributes( { backgroundColor: value, gradient: undefined } );
								},
								label: __( 'Background/Overlay Color', 'animated-raffle-winner' ),
							},
						] }
						gradientSettings={ [
							{
								value: gradient,
								onChange: ( value ) => {
									setAttributes( { gradient: value, backgroundColor: undefined } );
								},
								label: __( 'Background Gradient', 'animated-raffle-winner' ),
							},
						] }
					/>
					<RangeControl
						label={ __( 'Background/Overlay Opacity', 'animated-raffle-winner' ) }
						value={ overlayOpacity ?? 100 }
						onChange={ ( value ) =>
							setAttributes( { overlayOpacity: value ?? 100 } )
						}
						min={ 0 }
						max={ 100 }
						step={ 1 }
					/>
					<PanelColorSettings
						title={ __( 'Button Background Color', 'animated-raffle-winner' ) }
						colorSettings={ [
							{
								value: buttonColor,
								onChange: ( value ) => {
									setAttributes( { buttonColor: value } );
								},
								label: __( 'Button Background Color', 'animated-raffle-winner' ),
							},
						] }
					/>
					<PanelColorSettings
						title={ __( 'Button Text Color', 'animated-raffle-winner' ) }
						colorSettings={ [
							{
								value: buttonTextColor,
								onChange: ( value ) => {
									setAttributes( { buttonTextColor: value } );
								},
								label: __( 'Button Text Color', 'animated-raffle-winner' ),
							},
						] }
					/>
					<PanelColorSettings
						title={ __( 'Text Color', 'animated-raffle-winner' ) }
						colorSettings={ [
							{
								value: textColor,
								onChange: ( value ) => {
									setAttributes( { textColor: value } );
								},
								label: __( 'Text Color', 'animated-raffle-winner' ),
							},
						] }
					/>
					<p>{ __( 'Text Size', 'animated-raffle-winner' ) }</p>
					<ButtonGroup>
						{ textSizeOptions.map( ( option ) => (
							<Button
								key={ option.value }
								variant={ textSize === option.value ? 'primary' : 'secondary' }
								onClick={ () => setAttributes( { textSize: option.value } ) }
							>
								{ option.label }
							</Button>
						) ) }
					</ButtonGroup>
					<hr style={ { margin: '16px 0', borderColor: '#ddd' } } />
					<ToggleControl
						label={ __( 'Open in Fullscreen', 'animated-raffle-winner' ) }
						checked={ fullscreen }
						onChange={ ( value ) =>
							setAttributes( { fullscreen: value } )
						}
						help={ __( 'When enabled, the raffle will occupy the entire screen during the animation', 'animated-raffle-winner' ) }
					/>
					<SelectControl
						label={ __( 'Celebration Animation Type', 'animated-raffle-winner' ) }
						value={ animationType }
						options={ animationOptions }
						onChange={ ( value ) =>
							setAttributes( { animationType: value } )
						}
						help={ __( 'Choose the celebration style after revealing the result', 'animated-raffle-winner' ) }
					/>
				</PanelBody>
			</InspectorControls>

			<div { ...blockProps }>
				<div className={ `raffle-container text-size-${ textSize || 'medium' }` } style={ backgroundStyle }>
					<p className="raffle-message" style={ textStyle }>
						{ __( 'Raffling between', 'animated-raffle-winner' ) }{ ' ' }
						<strong style={ accentStyle }>{ startingNumber }</strong> { __( 'and', 'animated-raffle-winner' ) }{ ' ' }
						<strong style={ accentStyle }>{ endingNumber }</strong>
					</p>
					<button className="raffle-button" style={ buttonStyle } disabled>
						{ __( 'Draw', 'animated-raffle-winner' ) }
					</button>
					<div className="raffle-preview">
						<span className="number-preview" style={ accentStyle }>?</span>
					</div>
					<div className="raffle-config-info">
						<p className="raffle-info">
							{ __( 'Duration:', 'animated-raffle-winner' ) } <strong>{ raffleDuration }s</strong>
						</p>
						<p className="raffle-info">
							{ __( 'Fullscreen:', 'animated-raffle-winner' ) } <strong>{ fullscreen ? __( 'Yes', 'animated-raffle-winner' ) : __( 'No', 'animated-raffle-winner' ) }</strong>
						</p>
						<p className="raffle-info">
							{ __( 'Animation:', 'animated-raffle-winner' ) } <strong>{ animationOptions.find( opt => opt.value === animationType )?.label }</strong>
						</p>
					</div>
				</div>
			</div>
		</>
	);
}

/**
 * React hook that is used to mark the block wrapper element.
 * It provides all the necessary props like the class name.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-block-editor/#useblockprops
 */
import { useBlockProps, getGradientValueBySlug } from '@wordpress/block-editor';
import { __ } from '@wordpress/i18n';

/**
 * The save function defines the way in which the different attributes should
 * be combined into the final markup, which is then serialized by the block
 * editor into `post_content`.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-edit-save/#save
 *
 * @return {Element} Element to render.
 */
export default function save( { attributes } ) {
	const {
		startingNumber,
		endingNumber,
		raffleDuration,
		fullscreen,
		animationType,
		textSize,
		backgroundColor,
		overlayOpacity,
		gradient,
		buttonColor,
		textColor,
		buttonTextColor,
		backgroundImageUrl,
	} = attributes;

	const applyColorOpacity = ( colorValue, opacityValue ) => {
		const opacity = Math.max( 0, Math.min( 100, opacityValue ?? 100 ) ) / 100;
		const color = colorValue?.trim();

		if ( ! color ) {
			return colorValue;
		}

		const hexMatch = color.match( /^#([a-fA-F0-9]{3}|[a-fA-F0-9]{6})$/ );
		if ( hexMatch ) {
			const hex = hexMatch[ 1 ];
			const normalizedHex =
				hex.length === 3
					? hex.split( '' ).map( ( char ) => char + char ).join( '' )
					: hex;
			const red = parseInt( normalizedHex.slice( 0, 2 ), 16 );
			const green = parseInt( normalizedHex.slice( 2, 4 ), 16 );
			const blue = parseInt( normalizedHex.slice( 4, 6 ), 16 );
			return `rgba(${ red }, ${ green }, ${ blue }, ${ opacity })`;
		}

		const rgbMatch = color.match(
			/^rgba?\(\s*([0-9.]+)\s*,\s*([0-9.]+)\s*,\s*([0-9.]+)(?:\s*,\s*[0-9.]+\s*)?\)$/i
		);
		if ( rgbMatch ) {
			return `rgba(${ rgbMatch[ 1 ] }, ${ rgbMatch[ 2 ] }, ${ rgbMatch[ 3 ] }, ${ opacity })`;
		}

		return colorValue;
	};

	// Get background style - resolve gradient slug if needed
	// Sanitize CSS values to prevent injection
	// Supports custom multi-color gradients
	const backgroundStyle = {};
	if ( gradient ) {
		// Try to resolve gradient slug, fallback to direct value (supports custom gradients)
		const gradientValue = getGradientValueBySlug( gradient ) || gradient;
		// Sanitize gradient - block script injection attempts but allow CSS gradient syntax
		// Allows linear-gradient, radial-gradient, conic-gradient with multiple color stops
		if ( gradientValue && ! /<script|javascript:|on\w+\s*=/i.test( gradientValue ) ) {
			backgroundStyle.background = gradientValue;
		}
	} else if ( backgroundColor ) {
		// Sanitize color value - block script injection attempts
		if ( backgroundColor && ! /<script|javascript:|on\w+\s*=/i.test( backgroundColor ) ) {
			backgroundStyle.background = applyColorOpacity( backgroundColor, overlayOpacity );
		}
	}
	if ( backgroundImageUrl && ! /<script|javascript:/i.test( backgroundImageUrl ) ) {
		if ( gradient && backgroundStyle.background ) {
			backgroundStyle.backgroundImage = `${ backgroundStyle.background }, url("${ backgroundImageUrl }")`;
			delete backgroundStyle.background;
		} else if ( backgroundColor && backgroundStyle.background ) {
			const overlayColor = backgroundStyle.background;
			delete backgroundStyle.background;
			backgroundStyle.backgroundImage = `linear-gradient(${ overlayColor }, ${ overlayColor }), url("${ backgroundImageUrl }")`;
		} else {
			backgroundStyle.backgroundImage = `url("${ backgroundImageUrl }")`;
		}
		backgroundStyle.backgroundSize = 'cover';
		backgroundStyle.backgroundPosition = 'center';
		backgroundStyle.backgroundRepeat = 'no-repeat';
	}

	// Get button color style - sanitize CSS values to prevent injection
	const buttonStyle = {};
	if ( buttonColor ) {
		// Sanitize color value - block script injection attempts
		if ( buttonColor && ! /<script|javascript:|on\w+\s*=/i.test( buttonColor ) ) {
			buttonStyle.backgroundColor = buttonColor;
		}
	}
	if ( buttonTextColor ) {
		// Sanitize color value - block script injection attempts
		if ( buttonTextColor && ! /<script|javascript:|on\w+\s*=/i.test( buttonTextColor ) ) {
			buttonStyle.color = buttonTextColor;
		}
	}

	// Get text color style - sanitize CSS values to prevent injection
	const textStyle = {};
	if ( textColor ) {
		// Sanitize color value - block script injection attempts
		if ( textColor && ! /<script|javascript:|on\w+\s*=/i.test( textColor ) ) {
			textStyle.color = textColor;
		}
	}

	// Get accent color style for strong elements and raffle-result (uses button background color)
	const accentStyle = {};
	if ( buttonColor ) {
		// Sanitize color value - block script injection attempts
		if ( buttonColor && ! /<script|javascript:|on\w+\s*=/i.test( buttonColor ) ) {
			accentStyle.color = buttonColor;
		}
	}

	const blockProps = useBlockProps.save( {
		className: 'animated-raffle-winner-block',
	} );

	return (
		<div { ...blockProps }>
			<div
				className={ `raffle-container text-size-${ textSize || 'medium' }` }
				style={ backgroundStyle }
				data-starting-number={ startingNumber }
				data-ending-number={ endingNumber }
				data-raffle-duration={ raffleDuration }
				data-fullscreen={ fullscreen }
				data-animation-type={ animationType }
			>
				<p className="raffle-message" style={ textStyle }>
					{ __( 'Raffling between', 'animated-raffle-winner' ) }{ ' ' }
					<strong style={ accentStyle }>{ startingNumber }</strong> { __( 'and', 'animated-raffle-winner' ) }{ ' ' }
					<strong style={ accentStyle }>{ endingNumber }</strong>
				</p>
				<button
					className="raffle-button"
					style={ buttonStyle }
					type="button"
					data-draw-label={ __( 'Draw', 'animated-raffle-winner' ) }
					data-draw-again-label={ __( 'Draw again', 'animated-raffle-winner' ) }
				>
					{ __( 'Draw', 'animated-raffle-winner' ) }
				</button>
				<div className="raffle-result" role="status" aria-live="polite" aria-atomic="true">
					<span className="number-result" style={ accentStyle }></span>
				</div>
				<canvas className="celebration-canvas" aria-hidden="true"></canvas>
			</div>
		</div>
	);
}

/**
 * The following styles get applied both on the front of your site
 * and in the editor.
 *
 * Replace them with your own styles or remove the file completely.
 */

.animated-raffle-winner-block {
	margin: 2rem 0;

	.raffle-container {
		position: relative;
		text-align: center;
		padding: 3rem 2rem;
		// Default background - can be overridden by inline styles
		background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
		border-radius: 20px;
		box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
		overflow: hidden;
		transition: all 0.3s ease;

		&.fullscreen-active {
			position: fixed;
			top: 0;
			left: 0;
			width: 100vw;
			height: 100vh;
			z-index: 9999;
			border-radius: 0;
			margin: 0;
			display: flex;
			flex-direction: column;
			justify-content: center;
			align-items: center;
		}
	}

	.raffle-container.text-size-very-small {
		.raffle-message { font-size: 1.1rem; }
		.raffle-message strong { font-size: 1.3rem; }
		.raffle-button { font-size: 1.1rem; }
		.number-result, .number-preview { font-size: 3.5rem; }
		.number-result.rolling { font-size: 2.8rem; }
	}

	.raffle-container.text-size-small {
		.raffle-message { font-size: 1.3rem; }
		.raffle-message strong { font-size: 1.6rem; }
		.raffle-button { font-size: 1.3rem; }
		.number-result, .number-preview { font-size: 4.8rem; }
		.number-result.rolling { font-size: 3.8rem; }
	}

	.raffle-container.text-size-medium {
		.raffle-message { font-size: 1.5rem; }
		.raffle-message strong { font-size: 1.8rem; }
		.raffle-button { font-size: 1.5rem; }
		.number-result, .number-preview { font-size: 6rem; }
		.number-result.rolling { font-size: 4rem; }
	}

	.raffle-container.text-size-large {
		.raffle-message { font-size: 1.7rem; }
		.raffle-message strong { font-size: 2.1rem; }
		.raffle-button { font-size: 1.7rem; }
		.number-result, .number-preview { font-size: 6.8rem; }
		.number-result.rolling { font-size: 5.2rem; }
	}

	.raffle-container.text-size-super-large {
		.raffle-message { font-size: 1.9rem; }
		.raffle-message strong { font-size: 2.3rem; }
		.raffle-button { font-size: 1.9rem; }
		.number-result, .number-preview { font-size: 7.6rem; }
		.number-result.rolling { font-size: 5.8rem; }
	}

	.raffle-message {
		color: #fff;
		font-size: 1.5rem;
		margin-bottom: 2rem;
		text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);

		strong {
			font-size: 1.8rem;
			color: #ffd700;
		}
	}

	.raffle-button {
		background: #ffd700;
		color: #333;
		border: none;
		padding: 1rem 3rem;
		font-size: 1.5rem;
		font-weight: bold;
		border-radius: 50px;
		cursor: pointer;
		transition: all 0.3s ease;
		box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
		text-transform: uppercase;
		letter-spacing: 1px;

		&:hover {
			background: #ffed4e;
			transform: translateY(-2px);
			box-shadow: 0 7px 20px rgba(0, 0, 0, 0.4);
		}

		&:active {
			transform: translateY(0);
		}

		&:disabled {
			opacity: 0.6;
			cursor: not-allowed;
		}

		&.drawing {
			background: #ccc;
			cursor: wait;
		}
	}

	.raffle-result {
		margin-top: 2rem;
		min-height: 150px;
		display: flex;
		align-items: center;
		justify-content: center;
	}

	.number-result {
		display: inline-block;
		font-size: 6rem;
		font-weight: bold;
		color: #ffd700;
		text-shadow: 3px 3px 6px rgba(0, 0, 0, 0.5);
		opacity: 0;
		transform: scale(0);
		transition: all 0.5s ease;

		&.rolling {
			opacity: 1;
			transform: scale(1);
			font-size: 4rem;
			animation: roll 0.1s linear infinite;
		}

		&.revealed {
			opacity: 1;
			transform: scale(1);
			animation: reveal 0.8s ease-out;
		}
	}

	.raffle-preview {
		margin-top: 2rem;
		min-height: 150px;
		display: flex;
		align-items: center;
		justify-content: center;
	}

	.number-preview {
		font-size: 6rem;
		font-weight: bold;
		color: rgba(255, 255, 255, 0.3);
		text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
	}

	.raffle-config-info {
		margin-top: 1.5rem;
		display: flex;
		flex-wrap: wrap;
		justify-content: center;
		gap: 1rem;
	}

	.raffle-info {
		margin: 0;
		padding: 0.5rem 1rem;
		color: rgba(255, 255, 255, 0.8);
		font-size: 1rem;
		text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.3);
		background: rgba(0, 0, 0, 0.2);
		border-radius: 10px;

		strong {
			color: #ffd700;
			font-size: 1.1rem;
		}
	}

	.celebration-canvas {
		position: absolute;
		top: 0;
		left: 0;
		width: 100%;
		height: 100%;
		pointer-events: none;
		opacity: 0;
		transition: opacity 0.3s ease;

		&.active {
			opacity: 1;
		}
	}
}

@keyframes roll {
	0% {
		transform: scale(1) rotateX(0deg);
	}
	100% {
		transform: scale(1) rotateX(360deg);
	}
}

@keyframes reveal {
	0% {
		transform: scale(0) rotate(-180deg);
		opacity: 0;
	}
	50% {
		transform: scale(1.2) rotate(10deg);
	}
	100% {
		transform: scale(1) rotate(0deg);
		opacity: 1;
	}
}

/* Responsive */
@media (max-width: 768px) {
	.animated-raffle-winner-block {
		.raffle-message {
			font-size: 1.2rem;

			strong {
				font-size: 1.5rem;
			}
		}

		.raffle-button {
			font-size: 1.2rem;
			padding: 0.8rem 2rem;
		}

		.number-result {
			font-size: 4rem;

			&.rolling {
				font-size: 3rem;
			}
		}


		.number-preview {
			font-size: 4rem;
		}

		.raffle-info {
			font-size: 0.9rem;

			strong {
				font-size: 1rem;
			}
		}

		.raffle-config-info {
			flex-direction: column;
			align-items: center;
		}
	}
}

@media (prefers-reduced-motion: reduce) {
	.animated-raffle-winner-block {
		.raffle-container,
		.raffle-button,
		.number-result,
		.celebration-canvas {
			transition: none;
		}

		.number-result {
			&.rolling,
			&.revealed {
				animation: none;
			}
		}
	}
}

/**
 * The following styles get applied inside the editor only.
 *
 * Replace them with your own styles or remove the file completely.
 */

.animated-raffle-winner-block {
	.raffle-button {
		&:disabled {
			cursor: not-allowed;
			opacity: 0.7;
		}
	}

	.raffle-preview {
		margin-top: 2rem;
	}
}

/**
 * Use this file for JavaScript code that you want to run in the front-end
 * on posts/pages that contain this block.
 */

class AnimatedRaffleWinner {
	constructor( container ) {
		this.container = container;
		this.button = container.querySelector( '.raffle-button' );
		this.numberElement = container.querySelector( '.number-result' );
		this.canvas = container.querySelector( '.celebration-canvas' );
		this.ctx = this.canvas ? this.canvas.getContext( '2d' ) : null;
		this.drawLabel = this.button?.getAttribute( 'data-draw-label' ) || 'Draw';
		this.drawAgainLabel = this.button?.getAttribute( 'data-draw-again-label' ) || 'Draw again';

		// Validated allowed animation types
		const allowedAnimationTypes = ['fireworks', 'confetti', 'stars', 'balloons'];

		// Parse and validate numeric attributes
		const startingNumberRaw = parseInt(
			container.getAttribute( 'data-starting-number' ) || '1',
			10
		);
		const endingNumberRaw = parseInt(
			container.getAttribute( 'data-ending-number' ) || '100',
			10
		);
		const raffleDurationRaw = parseInt(
			container.getAttribute( 'data-raffle-duration' ) || '5',
			10
		);

		// Validate and constrain numeric values
		this.startingNumber = isNaN( startingNumberRaw ) || startingNumberRaw < -999999 || startingNumberRaw > 999999
			? 1
			: startingNumberRaw;
		this.endingNumber = isNaN( endingNumberRaw ) || endingNumberRaw < -999999 || endingNumberRaw > 999999
			? 100
			: endingNumberRaw;
		this.raffleDuration = isNaN( raffleDurationRaw ) || raffleDurationRaw < 1 || raffleDurationRaw > 60
			? 5
			: raffleDurationRaw;

		// Ensure ending number is greater than starting number
		if ( this.endingNumber <= this.startingNumber ) {
			this.endingNumber = this.startingNumber + 1;
		}

		this.fullscreen = container.getAttribute( 'data-fullscreen' ) === 'true';

		// Validate animation type against whitelist
		const animationTypeRaw = container.getAttribute( 'data-animation-type' ) || 'fireworks';
		this.animationType = allowedAnimationTypes.includes( animationTypeRaw )
			? animationTypeRaw
			: 'fireworks';

		this.particles = [];
		this.animationFrame = null;
		this.celebrationActive = false;
		this.keydownHandler = null;
		this.celebrationTimeout = null;
		this.reduceMotion = window.matchMedia &&
			window.matchMedia( '(prefers-reduced-motion: reduce)' ).matches;

		this.init();
	}

	init() {
		if ( this.button ) {
			this.button.addEventListener( 'click', () => this.startRaffle() );
		}

		if ( this.canvas ) {
			this.resizeCanvas();
			window.addEventListener( 'resize', () => this.resizeCanvas() );
		}
	}

	resizeCanvas() {
		if ( ! this.canvas ) {
			return;
		}
		this.canvas.width = this.container.offsetWidth;
		this.canvas.height = this.container.offsetHeight;
	}

	startRaffle() {
		if ( ! this.numberElement || ! this.button ) {
			return;
		}

		// Stop previous celebration if active
		this.stopCelebration();

		if ( this.fullscreen ) {
			this.container.classList.add( 'fullscreen-active' );
			this.resizeCanvas();
		}

		this.button.disabled = true;
		this.button.classList.add( 'drawing' );
		this.numberElement.classList.remove( 'revealed' );
		this.numberElement.classList.add( 'rolling' );

		const duration = this.raffleDuration * 1000;
		const interval = 100;
		const iterations = duration / interval;
		let counter = 0;

		const animation = setInterval( () => {
			const randomNumber =
				Math.floor(
					Math.random() * ( this.endingNumber - this.startingNumber + 1 )
				) + this.startingNumber;
			this.numberElement.textContent = randomNumber;

			counter++;
			if ( counter >= iterations ) {
				clearInterval( animation );
				this.revealResult();
			}
		}, interval );
	}

	revealResult() {
		const finalNumber =
			Math.floor(
				Math.random() * ( this.endingNumber - this.startingNumber + 1 )
			) + this.startingNumber;

		this.numberElement.textContent = finalNumber;
		this.numberElement.classList.remove( 'rolling' );
		this.numberElement.classList.add( 'revealed' );

		if ( this.button ) {
			this.button.disabled = false;
			this.button.classList.remove( 'drawing' );
			this.button.textContent = this.drawAgainLabel;
		}

		this.startCelebration();
		this.addKeyListener();
	}

	addKeyListener() {
		// Remove previous listener if exists
		if ( this.keydownHandler ) {
			document.removeEventListener( 'keydown', this.keydownHandler );
		}

		// Create new listener
		this.keydownHandler = ( e ) => {
			if ( this.celebrationActive && e.key === 'Escape' ) {
				e.preventDefault();
				this.stopCelebration();
				if ( this.fullscreen && this.container.classList.contains( 'fullscreen-active' ) ) {
					this.container.classList.remove( 'fullscreen-active' );
					this.resizeCanvas();
				}
				document.removeEventListener( 'keydown', this.keydownHandler );
				this.keydownHandler = null;
			}
		};

		document.addEventListener( 'keydown', this.keydownHandler );
	}

	stopCelebration() {
		if ( this.animationFrame ) {
			cancelAnimationFrame( this.animationFrame );
			this.animationFrame = null;
		}
		if ( this.celebrationTimeout ) {
			clearTimeout( this.celebrationTimeout );
			this.celebrationTimeout = null;
		}
		this.celebrationActive = false;
		this.particles = [];
		if ( this.canvas && this.ctx ) {
			this.ctx.clearRect( 0, 0, this.canvas.width, this.canvas.height );
			this.canvas.classList.remove( 'active' );
		}
	}

	startCelebration() {
		if ( ! this.canvas || ! this.ctx ) {
			return;
		}

		if ( this.reduceMotion ) {
			this.stopCelebration();
			return;
		}

		this.canvas.classList.add( 'active' );
		this.particles = [];
		this.celebrationActive = true;
		this.celebrationTimeout = setTimeout( () => this.stopCelebration(), 8000 );

		const animate = () => {
			if ( ! this.celebrationActive ) {
				return;
			}

			this.ctx.clearRect( 0, 0, this.canvas.width, this.canvas.height );

			switch ( this.animationType ) {
				case 'fireworks':
					if ( Math.random() < 0.1 ) {
						this.createFirework();
					}
					break;
				case 'confetti':
					if ( Math.random() < 0.3 ) {
						this.createConfetti();
					}
					break;
				case 'stars':
					if ( Math.random() < 0.2 ) {
						this.createStar();
					}
					break;
				case 'balloons':
					if ( Math.random() < 0.15 ) {
						this.createBalloon();
					}
					break;
			}

			this.updateParticles();
			this.drawParticles();

			this.animationFrame = requestAnimationFrame( animate );
		};

		animate();
	}

	createFirework() {
		const x = Math.random() * this.canvas.width;
		const y = Math.random() * ( this.canvas.height * 0.5 );
		const color = `hsl(${ Math.random() * 360 }, 100%, 60%)`;
		const particleCount = 50;

		for ( let i = 0; i < particleCount; i++ ) {
			const angle = ( Math.PI * 2 * i ) / particleCount;
			const velocity = 2 + Math.random() * 3;

			this.particles.push( {
				type: 'firework',
				x,
				y,
				vx: Math.cos( angle ) * velocity,
				vy: Math.sin( angle ) * velocity,
				color,
				life: 1,
				size: 2 + Math.random() * 3,
			} );
		}
	}

	createConfetti() {
		const x = Math.random() * this.canvas.width;
		const y = -20;
		const colors = ['#ff6b6b', '#4ecdc4', '#ffe66d', '#a8dadc', '#f1faee'];
		const color = colors[ Math.floor( Math.random() * colors.length ) ];

		this.particles.push( {
			type: 'confetti',
			x,
			y,
			vx: ( Math.random() - 0.5 ) * 2,
			vy: Math.random() * 2 + 1,
			rotation: Math.random() * 360,
			rotationSpeed: ( Math.random() - 0.5 ) * 10,
			color,
			life: 1,
			size: 5 + Math.random() * 5,
			shape: Math.random() > 0.5 ? 'square' : 'rectangle',
		} );
	}

	createStar() {
		const x = Math.random() * this.canvas.width;
		const y = Math.random() * this.canvas.height;
		const color = '#ffd700';

		this.particles.push( {
			type: 'star',
			x,
			y,
			vx: 0,
			vy: 0,
			scale: 0,
			color,
			life: 1,
			size: 20 + Math.random() * 20,
			points: 5,
		} );
	}

	createBalloon() {
		const x = Math.random() * this.canvas.width;
		const y = this.canvas.height + 50;
		const colors = ['#ff6b6b', '#4ecdc4', '#ffe66d', '#a8dadc', '#f1faee'];
		const color = colors[ Math.floor( Math.random() * colors.length ) ];

		this.particles.push( {
			type: 'balloon',
			x,
			y,
			vx: ( Math.random() - 0.5 ) * 0.5,
			vy: -( 1 + Math.random() * 1 ),
			oscillation: Math.random() * Math.PI * 2,
			color,
			life: 1,
			size: 20 + Math.random() * 15,
		} );
	}

	updateParticles() {
		this.particles = this.particles.filter( ( p ) => {
			switch ( p.type ) {
				case 'firework':
					p.x += p.vx;
					p.y += p.vy;
					p.vy += 0.1;
					p.life -= 0.01;
					break;

				case 'confetti':
					p.x += p.vx;
					p.y += p.vy;
					p.rotation += p.rotationSpeed;
					p.vy += 0.1;
					if ( p.y > this.canvas.height ) {
						p.life = 0;
					}
					break;

				case 'star':
					if ( p.scale < 1 ) {
						p.scale += 0.05;
					} else {
						p.life -= 0.02;
					}
					break;

				case 'balloon':
					p.x += p.vx + Math.sin( p.oscillation ) * 0.5;
					p.y += p.vy;
					p.oscillation += 0.1;
					if ( p.y < -50 ) {
						p.life = 0;
					}
					break;
			}

			return p.life > 0;
		} );
	}

	drawParticles() {
		this.particles.forEach( ( p ) => {
			this.ctx.save();
			this.ctx.globalAlpha = p.life;

			switch ( p.type ) {
				case 'firework':
					this.ctx.fillStyle = p.color;
					this.ctx.beginPath();
					this.ctx.arc( p.x, p.y, p.size, 0, Math.PI * 2 );
					this.ctx.fill();
					break;

				case 'confetti':
					this.ctx.translate( p.x, p.y );
					this.ctx.rotate( ( p.rotation * Math.PI ) / 180 );
					this.ctx.fillStyle = p.color;
					if ( p.shape === 'square' ) {
						this.ctx.fillRect( -p.size / 2, -p.size / 2, p.size, p.size );
					} else {
						this.ctx.fillRect( -p.size / 2, -p.size / 4, p.size, p.size / 2 );
					}
					break;

				case 'star':
					this.ctx.translate( p.x, p.y );
					this.ctx.scale( p.scale, p.scale );
					this.drawStar( 0, 0, p.points, p.size, p.size / 2, p.color );
					break;

				case 'balloon':
					this.drawBalloon( p.x, p.y, p.size, p.color );
					break;
			}

			this.ctx.restore();
		} );
	}

	drawStar( cx, cy, points, outerRadius, innerRadius, color ) {
		this.ctx.fillStyle = color;
		this.ctx.strokeStyle = color;
		this.ctx.lineWidth = 2;
		this.ctx.beginPath();

		for ( let i = 0; i < points * 2; i++ ) {
			const radius = i % 2 === 0 ? outerRadius : innerRadius;
			const angle = ( Math.PI * i ) / points - Math.PI / 2;
			const x = cx + Math.cos( angle ) * radius;
			const y = cy + Math.sin( angle ) * radius;

			if ( i === 0 ) {
				this.ctx.moveTo( x, y );
			} else {
				this.ctx.lineTo( x, y );
			}
		}

		this.ctx.closePath();
		this.ctx.fill();
		this.ctx.stroke();
	}

	drawBalloon( x, y, size, color ) {
		this.ctx.fillStyle = color;
		this.ctx.beginPath();
		this.ctx.ellipse( x, y, size * 0.6, size, 0, 0, Math.PI * 2 );
		this.ctx.fill();

		this.ctx.strokeStyle = color;
		this.ctx.lineWidth = 2;
		this.ctx.beginPath();
		this.ctx.moveTo( x, y + size );
		this.ctx.quadraticCurveTo( x + 5, y + size + 10, x, y + size + 20 );
		this.ctx.stroke();

		this.ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
		this.ctx.beginPath();
		this.ctx.ellipse( x - size * 0.2, y - size * 0.3, size * 0.15, size * 0.25, -0.3, 0, Math.PI * 2 );
		this.ctx.fill();
	}
}

document.addEventListener( 'DOMContentLoaded', () => {
	const containers = document.querySelectorAll( '.raffle-container' );
	containers.forEach( ( container ) => {
		new AnimatedRaffleWinner( container );
	} );
} );
